public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return Collections.emptyList();
    }
    // Ignore leading '/' in case of absolute path component
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split into segments, preserving empty segments
    String[] parts = rawPath.split("/", -1);
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>(parts.length);
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

