protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    Set<E> remaining = new LinkedHashSet<>(tour);
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    if (remaining.isEmpty()) {
        return new DefaultGraphPath<>(graph, vertexList, edgeList);
    }
    E first = remaining.iterator().next();
    V currentVertex = graph.getEdgeSource(first);
    vertexList.add(currentVertex);
    edgeList.add(first);
    remaining.remove(first);
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex) || tgt.equals(currentVertex)) {
                V nextVertex = src.equals(currentVertex) ? tgt : src;
                vertexList.add(nextVertex);
                edgeList.add(e);
                currentVertex = nextVertex;
                it.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Edges do not form a contiguous tour");
        }
    }
    return new DefaultGraphPath<>(graph, vertexList, edgeList);
}

