public static String applyRelativePath(String path,String relativePath){
    boolean isAbsolute = path.startsWith("/");
    String[] baseParts = path.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    for(String part: baseParts){
        if(part.isEmpty()||part.equals(".")) continue;
        if(part.equals("..")){
            if(!stack.isEmpty()) stack.pollLast();
        }else{
            stack.offerLast(part);
        }
    }
    String[] relParts = relativePath.split("/");
    for(String part: relParts){
        if(part.isEmpty()||part.equals(".")) continue;
        if(part.equals("..")){
            if(!stack.isEmpty()) stack.removeLast();
        }else{
            stack.offerLast(part);
        }
    }
    StringBuilder result = new StringBuilder();
    if(isAbsolute) result.append("/");
    java.util.Iterator<String> it = stack.iterator();
    while(it.hasNext()){
        result.append(it.next());
        if(it.hasNext()) result.append("/");
    }
    return result.toString();
}

