private void checkIfPackedField() throws IOException {
    if ((tag & 0x07) == 2 && isPackedField(fieldNumber)) { // 2 = WIRETYPE_LENGTH_DELIMITED
        packedSize = readVarint32();
        readingPacked = true;
    }
}

private String buildContentRange(){
    long start = this.contentRangeStart;
    long end = this.contentRangeEnd;
    long total = this.contentLength;
    if (start < 0 || end < 0 || total < 0) {
        return null;
    }
    return "bytes " + start + "-" + end + "/" + total;
}

List<ThreadSnapshot> function ( File file, List<ProfileAnalyzeTimeRange> timeRanges ) throws IOException { 
    List<ThreadSnapshot> all = parseFromFile(file); 
    List<ThreadSnapshot> result = new ArrayList<>(); 
    for (ThreadSnapshot ts : all) { 
        for (ProfileAnalyzeTimeRange tr : timeRanges) { 
            if (ts.getTimestamp() >= tr.getStartTime() && ts.getTimestamp() <= tr.getEndTime()) { 
                result.add(ts); 
                break; 
            } 
        } 
    } 
    return result; 
}
